mapper.sql:
FROM train t INNER JOIN train_stop stop_from ON stop_from.train_id = t.id AND stop_from.station_id = #{q.fromStationId} INNER JOIN train_stop stop_to ON stop_to.train_id = t.id AND stop_to.station_id = #{q.toStationId} WHERE t.status = 1 AND stop_from.stop_order < stop_to.stop_order AND EXISTS ( SELECT 1 FROM train_segment seg INNER JOIN train_segment_price price ON price.train_id = seg.train_id AND price.segment_index = seg.segment_index INNER JOIN ticket_stock stock ON stock.train_id = seg.train_id AND stock.segment_index = seg.segment_index AND stock.seat_type = price.seat_type AND stock.travel_date = #{q.travelDate} WHERE seg.train_id = t.id AND seg.segment_index BETWEEN stop_from.stop_order AND stop_to.stop_order - 1
AND price.seat_type = #{q.seatType}
)

mapper.select:
SELECT t.id AS train_id, t.train_no, t.train_type, station_from.station_name AS from_station_name, station_to.station_name AS to_station_name, stop_from.departure_time AS depart_time, stop_to.arrival_time AS arrive_time, TIMESTAMPDIFF( MINUTE, TIMESTAMP( DATE_ADD(DATE('2000-01-01'), INTERVAL stop_from.day_offset DAY), stop_from.departure_time ), TIMESTAMP( DATE_ADD(DATE('2000-01-01'), INTERVAL stop_to.day_offset DAY), stop_to.arrival_time ) ) AS duration_minutes, stop_to.mileage - stop_from.mileage AS mileage, price.seat_type, MIN(stock.remaining_count) AS remain_count, SUM(price.price) AS price FROM train t INNER JOIN train_stop stop_from ON stop_from.train_id = t.id AND stop_from.station_id = #{q.fromStationId} INNER JOIN train_stop stop_to ON stop_to.train_id = t.id AND stop_to.station_id = #{q.toStationId} INNER JOIN station station_from ON station_from.id = stop_from.station_id INNER JOIN station station_to ON station_to.id = stop_to.station_id INNER JOIN train_segment seg ON seg.train_id = t.id AND seg.segment_index BETWEEN stop_from.stop_order AND stop_to.stop_order - 1 INNER JOIN train_segment_price price ON price.train_id = seg.train_id AND price.segment_index = seg.segment_index INNER JOIN ticket_stock stock ON stock.train_id = seg.train_id AND stock.segment_index = seg.segment_index AND stock.seat_type = price.seat_type AND stock.travel_date = #{q.travelDate} WHERE t.status = 1 AND stop_from.stop_order < stop_to.stop_order AND t.id IN
#{trainId}
AND price.seat_type = #{q.seatType}
GROUP BY t.id, t.train_no, t.train_type, station_from.station_name, station_to.station_name, stop_from.day_offset, stop_from.departure_time, stop_to.day_offset, stop_to.arrival_time, stop_from.mileage, stop_to.mileage, price.seat_type ORDER BY price.seat_type
